const items = $input.all();

function pegarCustomField(issue, id) {
  const campo = (issue.custom_fields || []).find(
    c => Number(c.id) === Number(id)
  );

  return campo?.value ?? null;
}

function numeroOuNull(valor) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return null;
  }

  const numero = Number(valor);

  return Number.isNaN(numero)
    ? null
    : numero;
}

function booleanoRedmine(valor) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return null;
  }

  return String(valor) === '1';
}

return items.map(item => {

  const issue = item.json.issue || {};
  const agile = item.json.agile_data || {};

  const sprint = pegarCustomField(issue, 18);
  const remainingStoryPoints = pegarCustomField(issue, 14);
  const planejado = pegarCustomField(issue, 24);
  const impedimento = pegarCustomField(issue, 13);

  return {
    json: {

      // ============================================
      // ISSUE
      // ============================================

      issue_id: issue.id ?? null,

      issue_subject: issue.subject ?? '',
      issue_description: issue.description ?? '',


      // ============================================
      // PROJETO
      // ============================================

      project_id: issue.project?.id ?? null,
      project_name: issue.project?.name ?? '',


      // ============================================
      // TRACKER
      // ============================================

      tracker_id: issue.tracker?.id ?? null,
      tracker_name: issue.tracker?.name ?? '',


      // ============================================
      // STATUS ATUAL
      // ============================================

      status_id: issue.status?.id ?? null,
      status_name: issue.status?.name ?? '',
      status_is_closed: issue.status?.is_closed ?? false,


      // ============================================
      // PRIORIDADE
      // ============================================

      priority_id: issue.priority?.id ?? null,
      priority_name: issue.priority?.name ?? '',


      // ============================================
      // AUTOR
      // ============================================

      author_id: issue.author?.id ?? null,
      author_name: issue.author?.name ?? '',


      // ============================================
      // RESPONSÁVEL
      // ============================================

      assigned_to_id: issue.assigned_to?.id ?? null,
      assigned_to_name: issue.assigned_to?.name ?? '',


      // ============================================
      // ISSUE PAI
      // ============================================

      parent_id: issue.parent?.id ?? null,


      // ============================================
      // DATAS
      // ============================================

      start_date: issue.start_date ?? null,
      due_date: issue.due_date ?? null,

      created_on: issue.created_on ?? null,
      updated_on: issue.updated_on ?? null,
      closed_on: issue.closed_on ?? null,


      // ============================================
      // PROGRESSO / HORAS
      // ============================================

      done_ratio: numeroOuNull(issue.done_ratio),

      estimated_hours:
        numeroOuNull(issue.estimated_hours),

      spent_hours:
        numeroOuNull(issue.spent_hours),


      // ============================================
      // AGILE
      // ============================================

      story_points:
        numeroOuNull(agile.story_points),

      remaining_story_points:
        numeroOuNull(remainingStoryPoints),

      sprint_id:
        sprint === null || sprint === ''
          ? null
          : String(sprint),

      planejado:
        booleanoRedmine(planejado),

      flag_impedimento:
        booleanoRedmine(impedimento),


      // ============================================
      // REGRA DE ENTREGA
      // ============================================

      entregue_atualmente:
        Number(issue.status?.id) === 36,


      // ============================================
      // HISTÓRICO
      // ============================================

      journals:
        issue.journals || [],

      relations:
        issue.relations || [],

      children:
        issue.children || []

    }
  };

});

const items = $input.all();

// ======================================================
// CONFIGURAÇÕES DO FRAMEWORK
// ======================================================

const STATUS_INICIO_CYCLE_TIME = 27; // Em desenvolvimento
const STATUS_ENTREGA = 36;           // Concluído
const STATUS_REABERTO = 37;          // Reaberto


// ======================================================
// FUNÇÃO PARA DIFERENÇA ENTRE DATAS
// ======================================================

function diferencaHoras(dataInicial, dataFinal) {

  if (!dataInicial || !dataFinal) {
    return null;
  }

  const inicio = new Date(dataInicial);
  const fim = new Date(dataFinal);

  const diferencaMs = fim - inicio;

  if (diferencaMs < 0) {
    return null;
  }

  return Number(
    (diferencaMs / (1000 * 60 * 60)).toFixed(2)
  );
}


// ======================================================
// PROCESSA CADA ISSUE
// ======================================================

return items.map(item => {

  const issue = item.json;

  const journals = Array.isArray(issue.journals)
    ? issue.journals
    : [];


  // ====================================================
  // GUARDA TODAS AS MUDANÇAS DE STATUS
  // ====================================================

  const mudancasStatus = [];


  for (const journal of journals) {

    const detalhes = Array.isArray(journal.details)
      ? journal.details
      : [];

    for (const detalhe of detalhes) {

      if (
        detalhe.property === 'attr' &&
        detalhe.name === 'status_id'
      ) {

        mudancasStatus.push({
          journal_id: journal.id ?? null,

          data:
            journal.created_on ?? null,

          usuario_id:
            journal.user?.id ?? null,

          usuario_nome:
            journal.user?.name ?? '',

          status_anterior:
            detalhe.old_value !== null
              ? Number(detalhe.old_value)
              : null,

          status_novo:
            detalhe.new_value !== null
              ? Number(detalhe.new_value)
              : null
        });
      }
    }
  }


  // ====================================================
  // ORDENA CRONOLOGICAMENTE
  // ====================================================

  mudancasStatus.sort((a, b) => {
    return new Date(a.data) - new Date(b.data);
  });


  // ====================================================
  // PRIMEIRA ENTRADA EM DESENVOLVIMENTO
  // ====================================================

  const entradasDesenvolvimento =
    mudancasStatus.filter(
      m => m.status_novo === STATUS_INICIO_CYCLE_TIME
    );

  const inicioCycleTime =
    entradasDesenvolvimento.length > 0
      ? entradasDesenvolvimento[0].data
      : null;


  // ====================================================
  // ENTRADAS EM CONCLUÍDO
  // ====================================================

  const entregas =
    mudancasStatus.filter(
      m => m.status_novo === STATUS_ENTREGA
    );

  const primeiraEntrega =
    entregas.length > 0
      ? entregas[0].data
      : null;

  const ultimaEntrega =
    entregas.length > 0
      ? entregas[entregas.length - 1].data
      : null;


  // ====================================================
  // REABERTURAS
  // ====================================================

  const reaberturas =
    mudancasStatus.filter(
      m => m.status_novo === STATUS_REABERTO
    );

  const quantidadeReaberturas =
    reaberturas.length;


  // ====================================================
  // LEAD TIME
  //
  // Criação → primeira entrada em Concluído
  // ====================================================

  const leadTimeHoras =
    diferencaHoras(
      issue.created_on,
      primeiraEntrega
    );


  // ====================================================
  // CYCLE TIME
  //
  // primeira entrada em desenvolvimento → entrega
  // ====================================================

  const cycleTimeHoras =
    diferencaHoras(
      inicioCycleTime,
      primeiraEntrega
    );


  // ====================================================
  // RESULTADO
  // ====================================================

  return {
    json: {

      ...issue,

      // -----------------------------------------------
      // DATAS DO FLUXO
      // -----------------------------------------------

      cycle_started_on:
        inicioCycleTime,

      first_delivered_on:
        primeiraEntrega,

      last_delivered_on:
        ultimaEntrega,


      // -----------------------------------------------
      // MÉTRICAS
      // -----------------------------------------------

      lead_time_horas:
        leadTimeHoras,

      lead_time_dias:
        leadTimeHoras === null
          ? null
          : Number((leadTimeHoras / 24).toFixed(2)),

      cycle_time_horas:
        cycleTimeHoras,

      cycle_time_dias:
        cycleTimeHoras === null
          ? null
          : Number((cycleTimeHoras / 24).toFixed(2)),


      // -----------------------------------------------
      // QUALIDADE DO FLUXO
      // -----------------------------------------------

      quantidade_reaberturas:
        quantidadeReaberturas,

      ja_foi_entregue:
        primeiraEntrega !== null,


      // -----------------------------------------------
      // HISTÓRICO NORMALIZADO DE STATUS
      // -----------------------------------------------

      status_history:
        mudancasStatus

    }
  };

});

const items = $input.all();

const saida = [];

for (const item of items) {

  const issue = item.json;

  const historico = Array.isArray(issue.status_history)
    ? issue.status_history
    : [];

  for (let i = 0; i < historico.length; i++) {

    const h = historico[i];

    saida.push({
      json: {

        // ============================================
        // IDENTIFICAÇÃO DA ISSUE
        // ============================================

        issue_id: issue.issue_id ?? null,

        project_id: issue.project_id ?? null,
        project_name: issue.project_name ?? '',

        tracker_id: issue.tracker_id ?? null,
        tracker_name: issue.tracker_name ?? '',

        sprint_id: issue.sprint_id ?? null,


        // ============================================
        // JOURNAL
        // ============================================

        journal_id: h.journal_id ?? null,

        alterado_em: h.data ?? null,

        usuario_id: h.usuario_id ?? null,
        usuario_nome: h.usuario_nome ?? '',


        // ============================================
        // STATUS
        // ============================================

        status_anterior_id:
          h.status_anterior ?? null,

        status_novo_id:
          h.status_novo ?? null,


        // ============================================
        // ORDEM DA TRANSIÇÃO
        // ============================================

        ordem_transicao: i + 1

      }
    });
  }
}

return saida;

const items = $input.all();

const saida = [];

for (const item of items) {

  const issue = item.json;

  const journals = Array.isArray(issue.journals)
    ? issue.journals
    : [];

  for (const journal of journals) {

    const detalhes = Array.isArray(journal.details)
      ? journal.details
      : [];

    for (const detalhe of detalhes) {

      // ==========================================
      // CAMPO PERSONALIZADO 18 = SPRINT
      // ==========================================

      if (
        detalhe.property === 'cf' &&
        String(detalhe.name) === '18'
      ) {

        saida.push({
          json: {

            issue_id:
              issue.issue_id ?? null,

            project_id:
              issue.project_id ?? null,

            project_name:
              issue.project_name ?? '',

            journal_id:
              journal.id ?? null,

            alterado_em:
              journal.created_on ?? null,

            usuario_id:
              journal.user?.id ?? null,

            usuario_nome:
              journal.user?.name ?? '',

            sprint_anterior_id:
              detalhe.old_value === null ||
              detalhe.old_value === ''
                ? null
                : String(detalhe.old_value),

            sprint_nova_id:
              detalhe.new_value === null ||
              detalhe.new_value === ''
                ? null
                : String(detalhe.new_value)
          }
        });

      }
    }
  }
}

return saida;

const saida = [];

const inputs = $input.all();

function tratarValor(valor) {
  if (Array.isArray(valor)) {
    return valor.join(", ");
  }

  if (valor === null || valor === undefined) {
    return "";
  }

  return valor;
}

for (const input of inputs) {
  const projects = input.json.projects || [];

  for (const project of projects) {
    const customFields = project.custom_fields || [];

    const projetoTratado = {
      id: project.id || "",
      name: project.name || "",
      identifier: project.identifier || "",
      description: project.description || "",
      homepage: project.homepage || "",
      status: project.status ?? "",
      is_public: project.is_public ?? "",
      inherit_members: project.inherit_members ?? "",

      parent_id: project.parent?.id || "",
      parent_name: project.parent?.name || "",

      project_identifier: project.identifier || ""
    };

    // Transforma cada item de custom_fields em uma chave direta
    for (const campo of customFields) {
      const nomeCampo = campo.name || "";

      if (nomeCampo !== "") {
        projetoTratado[nomeCampo] = tratarValor(campo.value);
      }
    }

    projetoTratado.created_on = project.created_on || "";
    projetoTratado.updated_on = project.updated_on || "";

    saida.push({
      json: projetoTratado
    });
  }
}

return saida;

// ======================================================
// MONTAR - HIERARQUIA PROJETOS
//
// PRESERVA TODOS OS CAMPOS DO INPUT
// + acrescenta a hierarquia calculada.
//
// Estrutura semântica:
// 1 = Diretoria
// 2 = Área / Coordenação
// 3 = Tribo
// 4 = Squad
// 5 = Projeto
// 6 = Subprojeto
// ======================================================

const items = $input.all();


// ======================================================
// 1. RECUPERA TODOS OS PROJETOS
// ======================================================

const projetos = items.map(item => item.json);


// ======================================================
// 2. CRIA MAPA DOS PROJETOS POR ID
// ======================================================

const mapaProjetos = new Map();

for (const projeto of projetos) {

  if (
    projeto.id !== null &&
    projeto.id !== undefined &&
    projeto.id !== ''
  ) {

    mapaProjetos.set(
      String(projeto.id),
      projeto
    );

  }

}


// ======================================================
// 3. MONTA A CADEIA COMPLETA DE HIERARQUIA
// ======================================================

function montarHierarquia(projeto) {

  const cadeia = [];

  let atual = projeto;

  const visitados = new Set();


  while (atual) {

    const idAtual =
      String(atual.id ?? '');


    // Evita loop infinito caso exista
    // inconsistência na árvore do Redmine
    if (visitados.has(idAtual)) {
      break;
    }

    visitados.add(idAtual);


    // Adiciona o projeto atual na cadeia
    cadeia.unshift({

      id:
        atual.id ?? null,

      nome:
        atual.name ?? ''

    });


    const parentId =
      atual.parent_id ?? null;


    // Chegou ao topo da árvore
    if (
      parentId === null ||
      parentId === undefined ||
      parentId === ''
    ) {
      break;
    }


    const pai =
      mapaProjetos.get(
        String(parentId)
      );


    // Caso o pai não esteja presente
    // entre os projetos retornados
    if (!pai) {

      cadeia.unshift({

        id:
          parentId,

        nome:
          atual.parent_name ?? ''

      });

      break;

    }


    atual = pai;

  }


  return cadeia;

}


// ======================================================
// 4. PROCESSA TODOS OS PROJETOS
// ======================================================

return projetos.map(projeto => {

  const hierarquia =
    montarHierarquia(projeto);


  const profundidade =
    hierarquia.length;


  // ====================================================
  // IMPORTANTE:
  //
  // ...projeto preserva TODOS os campos recebidos
  // no input.
  //
  // Exemplo:
  // id
  // name
  // identifier
  // description
  // homepage
  // status
  // is_public
  // inherit_members
  // custom fields normalizados
  // Centro de custos
  // Tribo
  // Squad
  // Time
  // etc.
  // ====================================================

  const resultado = {

    ...projeto,


    // ==================================================
    // IDENTIFICAÇÃO NORMALIZADA
    // ==================================================

    project_id:
      projeto.id ?? null,

    project_name:
      projeto.name ?? null,

    project_identifier:
      projeto.identifier ??
      projeto.project_identifier ??
      null,


    // ==================================================
    // PAI IMEDIATO
    // ==================================================

    parent_id:
      projeto.parent_id ?? null,

    parent_name:
      projeto.parent_name ?? null,

    tem_projeto_pai:
      projeto.parent_id !== null &&
      projeto.parent_id !== undefined &&
      projeto.parent_id !== '',


    // ==================================================
    // PROFUNDIDADE
    // ==================================================

    profundidade:
      profundidade,


    // ==================================================
    // CAMINHO COMPLETO
    // ==================================================

    caminho_hierarquia:
      hierarquia
        .map(n => n.nome)
        .filter(Boolean)
        .join(' > ')

  };


  // ====================================================
  // 5. GARANTE OS 6 NÍVEIS GENÉRICOS
  //
  // Mesmo quando o nível não existe,
  // retornará null.
  // ====================================================

  for (let i = 0; i < 6; i++) {

    resultado[`nivel_${i + 1}_id`] =
      hierarquia[i]?.id ?? null;

    resultado[`nivel_${i + 1}_nome`] =
      hierarquia[i]?.nome ?? null;

  }


  // ====================================================
  // 6. SE EXISTIREM MAIS DE 6 NÍVEIS
  //
  // Também serão preservados.
  // ====================================================

  if (hierarquia.length > 6) {

    for (
      let i = 6;
      i < hierarquia.length;
      i++
    ) {

      resultado[`nivel_${i + 1}_id`] =
        hierarquia[i]?.id ?? null;

      resultado[`nivel_${i + 1}_nome`] =
        hierarquia[i]?.nome ?? null;

    }

  }


  // ====================================================
  // 7. DIRETORIA
  // NÍVEL 1
  // ====================================================

  resultado.diretoria_id =
    hierarquia[0]?.id ?? null;

  resultado.diretoria_nome =
    hierarquia[0]?.nome ?? null;


  // ====================================================
  // 8. ÁREA / COORDENAÇÃO
  // NÍVEL 2
  // ====================================================

  resultado.area_id =
    hierarquia[1]?.id ?? null;

  resultado.area_nome =
    hierarquia[1]?.nome ?? null;


  // ====================================================
  // 9. TRIBO
  // NÍVEL 3
  // ====================================================

  resultado.tribo_id =
    hierarquia[2]?.id ?? null;

  resultado.tribo_nome =
    hierarquia[2]?.nome ?? null;


  // ====================================================
  // 10. SQUAD
  // NÍVEL 4
  // ====================================================

  resultado.squad_id =
    hierarquia[3]?.id ?? null;

  resultado.squad_nome =
    hierarquia[3]?.nome ?? null;


  // ====================================================
  // 11. PROJETO
  // NÍVEL 5
  // ====================================================

  resultado.projeto_id =
    hierarquia[4]?.id ?? null;

  resultado.projeto_nome =
    hierarquia[4]?.nome ?? null;


  // ====================================================
  // 12. SUBPROJETO
  // NÍVEL 6
  // ====================================================

  resultado.subprojeto_id =
    hierarquia[5]?.id ?? null;

  resultado.subprojeto_nome =
    hierarquia[5]?.nome ?? null;


  // ====================================================
  // 13. INDICA SE É SUBPROJETO
  // ====================================================

  resultado.eh_subprojeto =
    profundidade >= 6;


  // ====================================================
  // 14. CLASSIFICA O NÓ ATUAL
  // ====================================================

  switch (profundidade) {

    case 1:

      resultado.tipo_hierarquia =
        'Diretoria';

      break;


    case 2:

      resultado.tipo_hierarquia =
        'Área / Coordenação';

      break;


    case 3:

      resultado.tipo_hierarquia =
        'Tribo';

      break;


    case 4:

      resultado.tipo_hierarquia =
        'Squad';

      break;


    case 5:

      resultado.tipo_hierarquia =
        'Projeto';

      break;


    default:

      resultado.tipo_hierarquia =
        profundidade >= 6
          ? 'Subprojeto'
          : null;

  }


  // ====================================================
  // 15. NÓ ATUAL DA ÁRVORE
  // ====================================================

  resultado.item_hierarquia_id =
    projeto.id ?? null;

  resultado.item_hierarquia_nome =
    projeto.name ?? null;


  // ====================================================
  // RETORNO
  // ====================================================

  return {
    json: resultado
  };

});

const saida = [];

const inputs = $input.all();

function tratarValor(valor) {
  if (Array.isArray(valor)) {
    return valor.join(", ");
  }

  if (valor === null || valor === undefined) {
    return "";
  }

  return valor;
}

for (const input of inputs) {
  const projects = input.json.projects || [];

  for (const project of projects) {
    const customFields = project.custom_fields || [];

    const projetoTratado = {
      id: project.id || "",
      name: project.name || "",
      identifier: project.identifier || "",
      description: project.description || "",
      homepage: project.homepage || "",
      status: project.status ?? "",
      is_public: project.is_public ?? "",
      inherit_members: project.inherit_members ?? "",

      parent_id: project.parent?.id || "",
      parent_name: project.parent?.name || "",

      project_identifier: project.identifier || ""
    };

    // Transforma cada item de custom_fields em uma chave direta
    for (const campo of customFields) {
      const nomeCampo = campo.name || "";

      if (nomeCampo !== "") {
        projetoTratado[nomeCampo] = tratarValor(campo.value);
      }
    }

    projetoTratado.created_on = project.created_on || "";
    projetoTratado.updated_on = project.updated_on || "";

    saida.push({
      json: projetoTratado
    });
  }
}

return saida;
